export const CreateObjectView = observer(({model}: {model: CreateObjectModel}) => {
  return (
    <div id="createObjectContainer">  {/* Added container div for context */}
      {/* Asset Selection & Creation Section */}
      <select id="assetSelection" onChange={(e) => {
        if (e.target.value) {
          model.createObject(e.target.value).then(() => {
            model.setSelectedAsset(e.target.value); 
          });
        }
      }}>
        {model.availableAssets.map((asset, index) => (
          <option key={index} value={asset}>{asset}</option>  {/* Added key and value attributes */}
        ))}
      </select>

      {/* Display Selected Asset (could enhance with dynamic ID based on asset) */}
      <div id="selectedAssetPreview">{ /* Display 'asset' here dynamically using model.selectedAsset */ }</div>

      {/* Cleanup Button */}
      <button id="cleanupButton" onClick={model.cleanupScene}>Cleanup scene</button>
    </div>
  )
})
```

