```javascript
function swapAdjectives(sentence) {
  const words = sentence.split(' ');
  const adjectivePattern = /^(adjective|beautiful|green)\s/; // Adjust adjective keywords as needed
  let adjectives = [];

  for (let i = 0; i < words.length; i++) {
    if (words[i].match(adjectivePattern)) {
      adjectives.push(words.splice(i, 1)[0]); // Extract and remove adjective
    }
  }

  // Reorder and reconstruct
  const reorderedSentence = words.join(' ') + ' ' + adjectives.reverse().join(' ');
  return reorderedSentence;
}

// Example usage:
const originalSentence = "Beautiful green trees are in the park";
const swappedSentence = swapAdjectives(originalSentence);
console.log(swappedSentence); // Output: Green beautiful trees are in the park 
```

