#include <iostream>
#include <limits>

using namespace std;

// Recursive Fibonacci function with error handling
int fibonacci(int a, int b, int n, int current) {
    if (n <= 0) return current;  // Base case: Stop recursion
    if (n == 1) return a;       // First element provided directly
    if (n == 2) return b;       // Second element provided directly
    return fibonacci(b, a + b, n - 1, a + b); // Recursive step
}

int main() {
    int start1, start2, count;

    cout << "Enter the first two integers for the Fibonacci sequence: ";
    while (!(cin >> start1 >> start2)) {  // Input validation for numeric values
        cout << "Invalid input. Please enter integers only: ";
        cin.clear();  // Clear error state
        cin.ignore(numeric_limits<streamsize>::max(), '\n'); // Discard invalid input
    }

    cout << "Enter the desired number of sequence elements: ";
    while (!(cin >> count) || count <= 0) {  // Validate count as positive integer
        cout << "Invalid input. Enter a positive integer: ";
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
    }

    // Generate and output the sequence
    if (start1 < 0 || start2 < 0) {
        cout << "Error: Starting integers cannot be negative. Sequence generation aborted." << endl;
        return 1; // Indicate an error
    }
    cout << start1 << ", " << start2 << ", ";
    for (int i = 3; i <= count; ++i) {
        int nextFib = fibonacci(start2, start1 + start2, i, start1 + start2); 
        cout << nextFib << " ";
        start1 = start2;
        start2 = nextFib;
    }
    cout << endl;

    return 0;
}
```

