using Newtonsoft.Json; // Assuming JSON serialization/deserialization

public class RestServiceWrapper<T> where T : class
{
    private readonly string _baseUrl;
    private readonly string _authTokenHeaderName = "Authorization";
    private readonly Func<Task<string>> _getAuthTokenAsync; // Delegate for obtaining fresh tokens

    public RestServiceWrapper(string baseUrl, Func<Task<string>> getAuthTokenAsync)
    {
        _baseUrl = baseUrl;
        _getAuthTokenAsync = getAuthTokenAsync;
    }

    protected virtual async Task<HttpResponseMessage> MakeRequestInternal(HttpMethod method, string relativeUrl, object content = null, Dictionary<string, string> additionalHeaders = null)
    {
        using (var client = new HttpClient())
        {
            string authToken = await _getAuthTokenAsync(); // Refresh token if needed
            client.DefaultRequestHeaders.Add(_authTokenHeaderName, $"Bearer {authToken}"); // Add Authorization header

            if (additionalHeaders != null)
                foreach (var header in additionalHeaders)
                    client.DefaultRequestHeaders.Add(header.Key, header.Value);

            HttpResponseMessage response;
            switch (method)
            {
                case HttpMethod.Get:
                    response = await client.GetAsync($"{_baseUrl}{relativeUrl}");
                    break;
                case HttpMethod.Post:
                    response = await client.PostAsync($"{_baseUrl}{relativeUrl}", content == null ? null : new StringContent(JsonConvert.SerializeObject(content), System.Text.Encoding.UTF8, "application/json"));
                    break;
                // ... Add other HTTP methods (Put, Delete, etc.) similarly
                default:
                    throw new ArgumentException($"Unsupported HTTP method: {method}");
            }

            return response;
        }
    }

    // Public API methods leveraging MakeRequestInternal
    public async Task<T> GetAsync(string relativeUrl) => 
        await DeserializeResponse<T>(await MakeRequestInternal(HttpMethod.Get, relativeUrl));

    public async Task<T> PostAsync(string relativeUrl, object data) => 
        await DeserializeResponse<T>(await MakeRequestInternal(HttpMethod.Post, relativeUrl, data));

