function determineMostRelevantProtocol(inputData) {
  // **Prioritize based on input cues and protocol characteristics:**

  // 1. IPv6 Address Presence (Strong Indicator): Both source and destination IPs are in IPv6 format.
  if (inputData.sourceIP.match(/^(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$/) && 
      inputData.destinationIP.match(/^(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$/)) {
    // IPv6 heavily suggests **IPv6 itself** as the foundational protocol in use, even though higher layers build upon it.
    return "IPv6"; 
  }

  // 2. Port and Payload (HTTP Indication): Port 80 is standard for HTTP.  Payload resembles text, further hinting at HTTP.
  if (inputData.port === 80 && typeof inputData.payload === 'string' && inputData.payload.trim() !== '') {
    return "HTTP"; 
  }

  // 3.  UDP Applicability (Less Direct but Possible): While not as strong a signal, UDP *could* be involved in underlying transport, especially without explicit TCP handshake data. However, given the HTTP indicators, it's less probable as the *primary* protocol in this scenario.
  //  We wouldn't definitively choose UDP here.

  // Default (Conservative):  Favor the most direct indicators found.
  return "HTTP"; 
}

