```typescript
import { Injectable } from '@nestjs/common';
import { CanActivate, ExecutionContext, UnauthorizedException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { TypeOrmModule } from '@nestjs/typeorm';
import { UserEntity } from './user.entity';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';

const PERMISSIONS = ['READ_DATA', 'WRITE_DATA', 'ADMIN']; // Example permission array

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(
    private reflector: Reflector,
    @InjectRepository(UserEntity) private userRepository: Repository<UserEntity>,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const requiredRoles = this.reflector.get<string[]>('roles', context.getHandler());
    if (!requiredRoles) return true; // No roles specified, allow access

    const request = context.switchToHttp().getRequest();
    const user = request.user as UserEntity;
    if (!user) throw new UnauthorizedException('User not authenticated');

    return requiredRoles.some(role => user.roles.includes(role));
  }
}

// ... (NestJS app setup, controllers with @UseGuards(RolesGuard), and role assignments in UserEntity model) ...
```

**Explanation (for context, NOT to be included in final `index.js`):**

- **`PERMISSIONS` Array:** Defines core permission names for your system. Adapt these to your exact needs.
- **`RolesGuard`:**
    - Retrieves `requiredRoles` metadata from controller methods using `@nestjs/core`'s `Reflector`.
    - Checks user authentication (assuming a working auth setup in your app, providing `user` in the request).
    - Compares user's assigned roles (`user.roles`) against required roles. Allows access only if there's a match.
    - Throws `UnauthorizedException` for missing permissions.
- **Integration:** This structure requires connecting `RolesGuard` to controllers via `@UseGuards(RolesGuard)` and managing user roles within your `UserEntity` model (database schema). 


