import { AuthGuard, CanActivate, ExecutionContext, ForbiddenException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { PrismaService } from './prisma.service';
import * as dotenv from 'dotenv';
dotenv.config();

interface Permission {
  name: string;
}

const PERMISSIONS: Permission[] = [
  { name: 'READ_USERS' },
  { name: 'CREATE_USERS' },
  { name: 'UPDATE_USERS' },
  { name: 'DELETE_USERS' },
  // ... add more permissions similarly
];

@Injectable()
export class RolesAuthGuard extends AuthGuard implements CanActivate {
  constructor(private reflector: Reflector, private prisma: PrismaService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const requiredRoles = this.reflector.get<string[]>('roles', context.getHandler());
    if (!requiredRoles) return true; // Public route

    const request = context.switchToHttp().getRequest();
    const user = request.user;
    if (!user || !user.roles) throw new ForbiddenException('Unauthorized');

    const hasRequiredRole = user.roles.some(role => requiredRoles.includes(role));
    return hasRequiredRole;
  }

  async checkPermissions(context: ExecutionContext, permissionName: string): Promise<void> {
    const user = context.switchToHttp().getRequest().user;
    if (!user || !user.roles) throw new ForbiddenException('Unauthorized');
    const userRoles = await this.prisma.user.findUnique({ where: { id: user.id } }).roles();
    if (!userRoles.some(role => PERMISSIONS.find(p => p.name === permissionName && role.permissions.includes(p.name)))) {
      throw new ForbiddenException(`Permission "${permissionName}" denied`);
    }
  }
}
``` 

**Explanation (for clarity, NOT part of the in-file output):**

1. **`PERMISSIONS` Array:** Defines a structured list of permission names used for authorization checks.
2. **`RolesAuthGuard`:**
   - Extends `AuthGuard` and implements `CanActivate` for route-level protection

