import { Injectable } from '@nestjs/common';
import { AuthGuard, CanActivate, ExecutionContext, UnauthorizedException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { UsersService } from './users.service'; // Assuming user data & roles are managed here
import { PERMISSIONS } from './permissions'; // Define your permission constants (array of strings) as an exported constant

@Injectable()
export class RolesAuthGuard extends AuthGuard implements CanActivate {
  constructor(private reflector: Reflector, private usersService: UsersService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const requiredRoles = this.reflector.get<string[]>('roles', context.getHandler());
    if (!requiredRoles) return true; // No roles specified, allow access

    const request = context.switchToHttp().getRequest();
    const user = request.user; 
    const userRoles = await this.usersService.getUserRoles(user.id); 

    return requiredRoles.some(role => userRoles.includes(role));
  }
  // Handle unauthorized cases with custom logic (e.g., UnauthorizedException)
  canActivateChild(context: ExecutionContext): boolean {
    return this.canActivate(context);
  }
}

