function geocodeAndStoreLatLng(spreadsheetId, sheetName, placeColumnName, latColumn, lngColumn) {
  // 1. Access Spreadsheet and Sheet
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(sheetName);

  // 2. Fetch Place Names and Store Results
  const lastRow = sheet.getLastRow(); // Find the last row with data
  for (let row = 2; row <= lastRow; row++) {  // Start from row 2 (assuming header row is row 1)
    const placeName = sheet.getRange(row, placeColumnName).getValue();
    if (placeName) {  // Only proceed if there's a place name in the cell
      try {
        const geocoder = new google.maps.Geocoder();
        const results = geocoder.geocode({'address': placeName});
        if (results && results.length > 0 && results[0].geometry.location) {
          const lat = results[0].geometry.location.lat();
          const lng = results[0].geometry.location.lng();

          // Store Latitude and Longitude in respective columns
          sheet.getRange(row, latColumn).setValue(lat);
          sheet.getRange(row, lngColumn).setValue(lng);
          Logger.log(`Successfully geocoded ${placeName} - Lat: ${lat}, Lng: ${lng}`);
        } else {
          Logger.log(`Geocoding failed for ${placeName}. No valid location found.`);
          // Handle cases where geocoding doesn't return results (optional: add error handling/notifications)
        }
      } catch (error) {
        Logger.error(`Error geocoding ${placeName}: ${error}`);
        // Robust error handling (log, notify, etc.) for unexpected issues
      }
    }
  }
}
