/**
 * Searches for a place name in a specified column and retrieves latitude/longitude, storing them in designated columns.
 *
 * @param {string} sheetName The name of the Google Sheet containing the data.
 * @param {string} placeNameColumn The header of the column with place names to search (e.g., "Place").
 * @param {string} latColumn The header where latitude values will be stored (e.g., "Latitude").
 * @param {string} lngColumn The header where longitude values will be stored (e.g., "Longitude").
 * @param {string} apiKey Your Google Maps Geocoding API Key (obtain from Google Cloud Console)
 */
function geocodeAndPopulate(sheetName, placeNameColumn, latColumn, lngColumn, apiKey) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(sheetName);
  const dataRange = sheet.getDataRange();
  const data = dataRange.getValues();

  // Iterate through each row containing a place name
  for (let row = 1; row < data.length; row++) {  // Skip header row (assuming row 1 contains headers)
    const placeName = data[row][placeNameColumn - 1]; // Adjust index for zero-based array

    if (placeName) {  // Only geocode if a place name exists
      const geocoder = new google.maps.Geocoder();
      const request = { address: placeName };
      geocoder.geocode(request, (results, status) => {
        if (status === google.maps.GeocoderStatus.OK) {
          const lat = results[0].geometry.location.lat();
          const lng = results[0].geometry.location.lng();
          sheet.getRange(row + 1, latColumn).setValue(lat);  // +1 to skip header row
          sheet.getRange(row + 1, lngColumn).setValue(lng);
        } else {
          Logger.log(`Geocoding failed for ${placeName}: ${status}`);
          // Handle geocoding errors (e.g., log, set an error marker in the sheet)
        }
      });
    }
  }
}
```

