function smart_sort_array(array $set, string $order = 'asc'): array {
    usort($set, function ($a, $b) use ($order) {
        $comparison = $a['age'] <=> $b['age']; // Efficient comparison using <=> operator

        return $order === 'asc' ? $comparison : -$comparison; 
    });

    return $set;
}

