function getValueByDotNotation(options, keyPath) {
  // Handle empty input for clarity
  if (!options || !keyPath) return undefined;

  const keys = keyPath.split('.');
  let currentLevel = options;

  // Traverse the nested object using the split keys
  for (const key of keys) {
    if (typeof currentLevel !== 'object' || currentLevel === null) {
      return undefined; // Key path doesn't exist in this structure
    }
    currentLevel = currentLevel[key];
  }

  return currentLevel; 
}
```

