function extractNestedValuesByDotNotation(options, keyString) {
  const keys = keyString.split('.');
  let currentLevel = options;

  // Traverse the nested structure using split keys
  for (const key of keys) {
    if (currentLevel && typeof currentLevel === 'object' && key in currentLevel) {
      currentLevel = currentLevel[key]; 
    } else {
      // Key sequence not found, return undefined (or handle as needed)
      return undefined; 
    }
  }

  return currentLevel; // Return the final matching value (or object if traversal complete)
}
```

