% Earth Ellipsoid Parameters (WGS84)
a = 6378137;  % Semi-major axis (meters)
b = 6356752.3142; % Semi-minor axis (meters)
f = (a-b)/a;   % Flattening
e2 = 2*f - f^2; % Eccentricity squared

% Input Coordinates (Degrees, converted to radians)
lat1 = deg2rad(37.7749); % San Francisco latitude
lon1 = deg2rad(-122.4194); % San Francisco longitude
lat2 = deg2rad(51.5074); % London latitude
lon2 = deg2rad(-0.1278); % London longitude

% Radius of Curvature Calculations (assuming h1 and h2 = 0 for simplicity, no altitude)
N1 = a / sqrt(1 - e2 * sin(lat1)^2);
N2 = a / sqrt(1 - e2 * sin(lat2)^2);

% Cartesian Coordinates Calculation
x1 = (N1)*cos(lat1)*cos(lon1);
y1 = (N1)*cos(lat1)*sin(lon1);
z1 = ((1-e2)*N1)*sin(lat1);
x2 = (N2)*cos(lat2)*cos(lon2);
y2 = (N2)*cos(lat2)*sin(lon2);
z2 = ((1-e2)*N2)*sin(lat2);

% Distance Calculation (Euclidean distance in ellipsoid model)
d = sqrt((x1-x2)^2 + (y1-y2)^2 + (z1-z2)^2);

% Display Result
disp(['The distance between San Francisco and London (ellipsoidal model) is: ', num2str(d), ' meters']);
```

