x2 = (N2)*cos(lat2)*cos(lon2);
y2 = (N2)*cos(lat2)*sin(lon2);
z2 = ((1-e2)*N2)*sin(lat2);

% Calculate Distance
d = sqrt((x1-x2)^2 + (y1-y2)^2 + (z1-z2)^2);

% Display Result (in kilometers for clarity)
distance_km = d / 1000;
fprintf('The distance between San Francisco and London (ellipsoidal model) is: %.2f km\n', distance_km);
