    public float dbScale = 20f;     // Adjusts visual intensity based on dB values

    private float[] bandBuffer = new float[frequencyBands];
    private Texture2D spectrumTexture;

    void Start()
    {
        // Initialize Spectrum Texture
        spectrumTexture = new Texture2D(frequencyBands, 128, TextureFormat.ARGB32, false);
        spectrumDisplay.texture = spectrumTexture;

        // Ensure audio source is set up
        if (!audioSource)
        {
            Debug.LogError("AudioSource not assigned in Inspector! Attach one to this script.");
            return;
        }
        audioSource.clip = Resources.Load<AudioClip>("YourAudioFile"); // Replace "YourAudioFile" with your actual audio asset path
        audioSource.Play(); // Start playback
    }

    void Update()
    {
        // 1. Analyze Audio Spectrum
        AudioListener.GetSpectrumData(bandBuffer, 0, FFTWindow.Blackman);

        // 2. Visual Representation (Mapping dB to Pixels)
        for (int i = 0; i < frequencyBands; i++)
        {
            float bandIntensity = bandBuffer[i] * dbScale; // Scale dB values for visualization
            int pixelHeight = (int)(bandIntensity * spectrumTexture.height); // Map to texture height

            // Color the band in the texture
            Color color = new Color(i / (float)frequencyBands, 0, 1 - (i / (float)frequencyBands), bandIntensity); // Gradient effect
            for (int y = 0; y < pixelHeight; y++)
            {
                spectrumTexture.SetPixel(i, y, color);
            }
        }

        // 3. Update Texture on UI
        spectrumTexture.Apply(); // Crucial for changes to show
    }
}
