fn is_even(n: i32) -> bool {
    if n == 0 { true }
    else if n == 1 { false }
    else if n == 2 { true }
    else if n == 3 { false }
    else if n == 4 { true }
    else if n == 5 { false }
    else if n == 6 { true }
    else if n == 7 { false }
    else if n == 8 { true }
    else if n == 9 { false }
    else if n == 10 { true }
    else {
