#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* argvToCString(int argc, char **argv) {
    // 1. Calculate total string length (excluding null terminators)
    size_t totalLength = 0;
    for (int i = 0; i < argc; ++i) {
        totalLength += strlen(argv[i]) + 1; // Add 1 for separating spaces
    }

    // 2. Allocate memory for the combined string
    char *combinedString = malloc(totalLength);
    if (combinedString == NULL) {
        fprintf(stderr, "Memory allocation failed!\n");
        exit(1); // Handle memory error gracefully
    }

    // 3. Construct the concatenated string
    char *currentPos = combinedString;
    for (int i = 0; i < argc; ++i) {
        strcpy(currentPos, argv[i]);  // Copy each argument
        currentPos += strlen(argv[i]);
        *currentPos++ = ' '; // Add space separator
    }
    *--currentPos = '\0'; // Ensure null termination at the end

    return combinedString;
}

int main(int argc, char **argv) {
    char *combinedArgs = argvToCString(argc, argv);
    printf("Combined command-line arguments as a C-style string: %s\n", combinedArgs);
    free(combinedArgs); // Memory cleanup
    return 0;
}
