```typescript
import { Injectable, MiddlewareFn } from '@nestjs/common';

@Injectable()
export const EnvironmentCheckDecorator = (envVar: string = 'NODE_ENV') => {
  return (target: Object, propertyKey: string | symbol, descriptor: PropertyDescriptor) => {
    const originalMethod = descriptor.value;

    descriptor.value = async function (...args: any[]) {
      const envValue = process.env[envVar];
      if (envValue && envValue.toLowerCase() === 'true') {
        // Production or development (depending on your 'true' definition), proceed with middleware execution
        return await originalMethod.apply(this, args); 
      } else {
        // Non-production environment, short-circuit execution
        return false; 
      }
    };

    return descriptor;
  };
};

// Usage Example:

@Middleware(EnvironmentCheckDecorator('NODE_ENV')) // Applies the decorator to a Nest.js middleware
export class MyConditionalMiddleware implements MiddlewareFn {
  async execute(context: any, next: () => Promise<any>) {
    // ... your middleware logic ... (only executed in 'true' NODE_ENV)
    return next(); 
  }
}
```

