import React, { useState, useRef } from 'react';
import { Combobox, ComboboxInput, ComboboxList, ComboboxOption } from 'downshift';
import { searchEmails } from './emailService'; // Assuming your async function resides here

const EmailAutocomplete = () => {
  const [emails, setEmails] = useState<string[]>([]);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleInputChange = async (inputValue: string) => {
    if (inputValue.length > 2) { // Trigger search after at least 3 characters
      const results = await searchEmails(inputValue);
      setEmails(results);
    } else {
      setEmails([]); // Clear suggestions on shorter inputs
    }
  };

  return (
    <Combobox onChange={(_, selectedItem) => {
      // Update input with selected email on choice
      inputRef.current?.value = selectedItem || ''; 
    }}>
      <ComboboxInput
        ref={inputRef}
        placeholder="Enter email address"
        onChange={handleInputChange}
        width={300} // Adjust width as needed
      />
      <ComboboxList>
        {emails.map((email) => (
          <ComboboxOption key={email} value={email}>
            {email}
          </ComboboxOption>
        ))}
      </ComboboxList>
    </Combobox>
  );
};

export default EmailAutocomplete;
```

