using System.Linq;

public class NaiveBayesTextClassifier
{
    private readonly NaiveBayes _classifier;
    private readonly Dictionary<string, int> _categoryToIndex;

    public NaiveBayesTextClassifier(List<Tuple<string, string>> dataset)
    {
        // 1. Data Preparation & Vectorization
        var vectorizer = new CountVectorizer();
        var featureMatrix = vectorizer.Transform(dataset.Select(x => x.Item1).ToArray()); // Sentences as input

        // 2. Map Categories to Indices for Model
        _categoryToIndex = dataset.GroupBy(x => x.Item2).Select((g, i) => new { Category = g.Key, Index = i }).ToDictionary(x => x.Category, x => x.Index);
        var labels = dataset.Select(x => _categoryToIndex[x.Item2]).ToArray(); // Numerical labels

        // 3. Train Naive Bayes Model
        _classifier = new NaiveBayes(featureMatrix, labels); 
    }

    public string Classify(string sentence)
    {
        // 4. Predict using Trained Model
        var features = new CountVectorizer().Transform(new[] { sentence }); // Vectorize new sentence
        var predictions = _classifier.Decide(features);
        return _categoryToIndex.Reverse().Where(x => x.Value == predictions[0]).Select(x => x.Key).FirstOrDefault();
    }

