public class NaiveBayesTextClassifier
{
    public static void Main(string[] args)
    {
        // 1. Data Preparation (Simulated for brevity, replace with your real dataset loading)
        var dataset = new List<Tuple<string, string>>
        {
            ("The debate sparked controversy.", "Politics"),
            ("Ronaldo scored a stunning goal.", "Sports"),
            ("New movie premiere delights fans.", "Entertainment"),
            // ... populate with more labeled sentences for robust training
        };

        // 2. Feature Extraction (Word Counts with CountVectorizer)
        var vectorizer = new CountVectorizer();
        var featureMatrix = vectorizer.Transform(dataset.Select(x => x.Item1).ToArray());

        // 3. Label Encoding (Mapping categories to numerical values)
        var labels = dataset.Select(x => x.Item2).Distinct().ToList();
        var encoder = new OneHotEncoder();
        var encodedLabels = encoder.FitTransform(labels.Select(l => l).ToArray()); // Adapt encoding as needed

        // 4. Naive Bayes Model Training
        var naiveBayes = new NaiveBayes<double>(encodedLabels.Length); // Length matches label count
        naiveBayes.Learn(featureMatrix, encodedLabels.Select(l => l.ToArray()).ToArray());

        // 5. Conditional Probability Calculation (Implicit in trained model)
        //   -  Naive Bayes stores these during training. Access via model's internal parameters.

        // 6. Classification - Example Sentence
        string newSentence = "The sports game was exciting.";
        var newFeatureVector = vectorizer.Transform(new string[] { newSentence });
        var prediction = naiveBayes.Decide(newFeatureVector);
        var predictedLabel = encoder.InverseTransform(prediction)[0]; // Map back to original category

        Console.WriteLine($"Prediction for '{newSentence}': {predictedLabel}");
    }
}
```

