using System.Collections.Generic;

public class NaiveBayesTextClassifier
{
    public static void Main(string[] args)
    {
        // 1. Prepare Dataset (Simulated for brevity, replace with your real labeled data)
        var dataset = new List<(string Sentence, string Category)>()
        {
            ("Basketball playoffs intense!", "Sports"),
            ("New policy sparks debate", "Politics"),
            ("Movie premiere red carpet glamour", "Entertainment"),
            // ... add more sentences and labels for robust training
        };

        // 2. Feature Extraction with CountVectorizer
        var vectorizer = new CountVectorizer();
        var featureMatrix = vectorizer.Transform(dataset.Select(x => x.Sentence).ToArray()); 

        // 3. Label Encoding (Accord handles this internally)
        var labels = dataset.Select(x => x.Category).ToArray();

        // 4. Train Naive Bayes Model
        var naiveBayes = new NaiveBayes<Gaussian>() {  Normalize = true }; // Gaussian distribution assumption common for word counts
        naiveBayes.Train(featureMatrix, labels);

        // 5. Conditional Probability Analysis (Conceptual -  model stores these)
