        // 6. Classification - New Sentence Prediction
        string testSentence = "The sports game was exciting";
        var transformedTest = vectorizer.Transform(new[] { testSentence });
        string predictedCategory = naiveBayes.Decide(transformedTest)[0];

        Console.WriteLine($"Sentence: \"{testSentence}\"  -> Predicted Category: {predictedCategory}");
    }
}
```

