```swift
import Foundation

func optimisticRearrangement(_ phrase: String) -> String {
    // 1. **Extract & Prioritize Positive Vibes:**  Identify and preferentially arrange letters commonly found in words evoking optimism and gratitude (e.g., "joy", "love", "thank", "hope", "bless"). Create a custom priority dictionary mapping these letters to higher sorting values.

    let positivityPrioritization = ["j": 10, "o": 8, "y": 7, "l": 6, "v": 5, "e": 4, "t": 3, "h": 3, "a": 2, "n": 2, "k": 2, "g": 2, "r": 1, "d": 1] //  Assign higher values for stronger optimism keywords

    // 2. Weighted Sorting with Emphasis:
    let sortedLetters = phrase.lowercased().filter { !$0.isWhitespace }
        .sorted { (a, b) -> Bool in
            guard let priorityA = positivityPrioritization[a], let priorityB = positivityPrioritization[b] else { return a < b } // Prioritize optimism letters
            return priorityA > priorityB // Higher priority comes first
    }

    // 3.  Construct Encouraging Phrase:
    let rearrangedPhrase = String(sortedLetters)
    return "Embrace the positive: \(rearrangedPhrase)  Cultivate gratitude and hope!" 

}

