```swift
import Foundation

func infuseOptimismAndGratitude(_ phrase: String) -> String {
    // 1. Extract & Prioritize Positive Vibes:
    let coreKeywords = ["joy", "hope", "thank", "bless", "grate", "love", "strength", "abundance"].compactMap { keyword in
        phrase.lowercased().contains(keyword) ? keyword : nil
    }
    var prioritizedLetters = Array(phrase.filter { !$0.isWhitespace })
    prioritizedLetters.append(contentsOf: coreKeywords.joined().lowercased().map { $0 }) // Weave keywords organically

    // 2.  Structured Rearrangement with Optimistic Flow:
    prioritizedLetters.sort {
        if $0.localizedCaseInsensitiveCompare($1) == .orderedAscending { return true }
        // Prioritize keywords, then alphabetical order for remaining letters
        return coreKeywords.firstIndex(of: String($0)) ?? Int.max < coreKeywords.firstIndex(of: String($1)) ?? Int.max 
    }

    // 3.  Craft the Gratitude-Infused Output:
    let rearrangedPhrase = String(prioritizedLetters)
    return "Embrace the good with \(rearrangedPhrase), and cultivate gratitude daily!" 
}

