```swift
import Foundation

func optimisticGratitudeRearrangement(_ phrase: String) -> String {
    // 1.  Sentiment Infusion: Prioritize positive keywords
    let positivityBoost = ["grate", "hope", "joy", "love", "thank"].compactMap { keyword in
        phrase.lowercased().contains(keyword) ? keyword : nil
    }.first ?? "" // Choose the first found positive keyword, if any

    // 2.  Structured Rearrangement: Blend alphabetical order with emphasis
    let sortedLetters = phrase.filter { !$0.isWhitespace }.sorted()
    var rearranged = String(sortedLetters)

    //  3.  Optimistic Placement:  Weave in positivity boost strategically
    if !positivityBoost.isEmpty {
        let boostIndex = rearranged.firstIndex(where: { $0 == " " }) ?? rearranged.endIndex // Find a space or end for insertion
        rearranged = String(rearranged.prefix(boostIndex)) + positivityBoost + String(rearranged.suffix(rearranged.distance(from: boostIndex, to: rearranged.endIndex))) 
    }

    // 4. Gratitude Emphasis: Subtle rearrangement around "thank" (if present)
    if rearranged.contains("thank") {
        let thankIndex = rearranged.firstIndex(of: "thank")!
        rearranged = String(rearranged.prefix(thankIndex)) + "thankful" + String(rearranged.suffix(rearranged.distance(from: thankIndex + "thank".count, to: rearranged.endIndex)))
    }

    // 5.  Final Flourish:  Return with a grateful sentiment
    return "Embrace life with \(rearranged) and heartfelt gratitude!"
}

