import * as Chart from 'chart.js'; // Assuming Chart.js for visualization

// Function to construct and display the bar chart
async function generateBarChart(dataset: { label: string, value: number }[]) {
  const ctx = document.getElementById('myChart') as HTMLCanvasElement; // Get canvas element (ensure it exists in your HTML)
  if (!ctx) {
    console.error("Canvas element with id 'myChart' not found. Chart generation failed.");
    return;
  }

  const chartData = {
    labels: dataset.map(item => item.label),
    datasets: [{
      label: 'Values',
      data: dataset.map(item => item.value),
      backgroundColor: ['#4CAF50', '#FF9800', '#F44336', ...gradientColors(dataset.length)], // Colorful bars
      borderWidth: 1,
      borderColor: '#fff',
      hoverOffset: 4
    }]
  };

  const chartOptions = {
    scales: {
      y: {
        beginAtZero: true,
        title: {
          display: true,
          text: 'Values'
        }
      },
      x: {
        title: {
          display: true,
          text: 'Categories'
        }
      }
    },
    responsive: true,
    plugins: {
      legend: {
        position: 'top', // Adjust legend placement as needed
      }
    }
  };

  // Helper to create gradient colors for more data points
  function gradientColors(count: number) {
    const gradient hues = ['#4CAF50', '#FF9800', '#F44336', '#2196F3', '#9C27B0']; // Example hues
    return Array.from({ length: count - 3 }, (_, i) => gradient hues[(i % gradient hues.length)]);
  }

  new Chart(ctx, {
    type: 'bar',
    data: chartData,
    options: chartOptions
  });
}

