import React, { useEffect, useRef } from 'react';

const RemoveWidow = ({ children }) => {
  const paragraphRef = useRef(null);

  useEffect(() => {
    // Function to handle widow removal (adjust logic as needed for stricter control)
    const removeWidowLines = () => {
      if (paragraphRef.current) {
        const paragraphs = paragraphRef.current.querySelectorAll('p');
        paragraphs.forEach(p => {
          // 1. Check if last line has fewer than X characters (threshold, e.g., 30)
          const lastLineText = p.lastChild.textContent.trim();
          if (lastLineText.length < 30) { 
            // 2.  Optionally, merge last line with preceding one while preserving context
            const prevSibling = p.previousSibling;
            if (prevSibling && prevSibling.tagName === 'P') {
              prevSibling.appendChild(p.lastChild);
              p.removeChild(p.lastChild); 
            } else {
              //  3.  If no suitable merge, add a non-breaking space at the end  (soft solution)
              p.lastChild.textContent += ' '; // Non-breaking space (\u00A0)
            }
          }
        });
      }
    };

    removeWidowLines(); // Initial cleanup
    // Add event listener for dynamic content updates (optional but recommended)
    const observer = new MutationObserver(removeWidowLines);
    observer.observe(paragraphRef.current, { childList: true, subtree: true });

    return () => observer.disconnect(); // Cleanup on component unmount
  }, []);

  return <div ref={paragraphRef}>{children}</div>;
};

export default RemoveWidow;
```

