import { useEffect, useRef } from 'react';

const useRemoveWidowChars = () => {
  const textRef = useRef(null); 

  useEffect(() => {
    if (textRef.current) {
      // Function to handle widow removal (prioritize clarity and conciseness)
      const removeWidowChars = () => {
        const textContent = textRef.current.textContent;
        const processedText = textContent
          .replace(/(\w)\s+$/g, '$1') // Remove trailing whitespace followed by a word character
          .trim(); // Ensure overall trailing whitespace removal
        textRef.current.textContent = processedText;
      };

      removeWidowChars(); // Initial cleanup on mount
      // Optional: Add debouncing for dynamic content updates (performance)
