      // window.addEventListener('input', debouncedRemove); 
      // Cleanup on unmount to prevent memory leaks
      return () => window.removeEventListener('input', removeWidowChars); 
    }
  }, []); // Empty dependency array ensures effect runs only once on mount

  return { textRef };
};

export default useRemoveWidowChars;
