       if (user) {
         // User is signed in, 'user.uid' is a unique session-linked ID
         console.log("Current User UID (session-related):", user.uid); 
         // Access other user data and session info within 'user' object
       } else {
         // User is not signed in, no active session
       }
     });
     ```

