// utils/redis.js

const redis = require('redis');

class RedisClient {
  constructor(host = 'localhost', port = 6379) {
    this.client = redis.createClient({ host, port });

    // Handle Redis client errors
    this.client.on('error', (err) => console.error(`Redis Client Error: ${err}`));
  }

  isAlive() {
    return new Promise((resolve) => {
      this.client.ping((err, reply) => {
        resolve(!err && reply === 'PONG');
      });
    });
  }

  async get(key) {
    try {
      return await this.client.get(key);
    } catch (err) {
      console.error(`Error fetching from Redis (key: ${key}):`, err);
      throw err; // Re-throw for proper async error handling
    }
  }

  async set(key, value, durationInSeconds) {
    try {
      await this.client.set(key, value, 'EX', durationInSeconds);
      console.log(`Value set for key "${key}" with expiration in ${durationInSeconds} seconds`);
    } catch (err) {
      console.error(`Error setting in Redis (key: ${key}):`, err);
      throw err;
    }
  }

  async del(key) {
    try {
      const result = await this.client.del(key);
      console.log(`Deleted key "${key}" (result: ${result})`);
      return result === 1; // Return true if deletion successful
    } catch (err) {
      console.error(`Error deleting from Redis (key: ${key}):`, err);
      throw err;
    }
  }
}

// Export an instance for use
const redisClient = new RedisClient();
module.exports = redisClient;
```

