class RedisClient {
  constructor(host = 'localhost', port = 6379) {
    this.client = redis.createClient({ host, port });

    // Error handling - log errors to the console
    this.client.on('error', (err) => console.error(`Redis Client Error: ${err}`));
  }

  isAlive() {
    return new Promise((resolve) => {
      this.client.ping((err, reply) => {
        if (err) {
          resolve(false); // Connection issue
        } else {
          resolve(true); // Connected successfully
        }
      });
    });
  }

  async get(key) {
    try {
      const value = await this.client.get(key);
      return value;
    } catch (err) {
      console.error(`Redis GET Error for key "${key}":`, err);
      throw err; // Re-throw for proper async error handling
    }
  }

  async set(key, value, durationInSeconds) {
    try {
      await this.client.set(key, value, 'EX', durationInSeconds);
      return true; // Successful set
    } catch (err) {
      console.error(`Redis SET Error for key "${key}":`, err);
      throw err;
    }
  }

  async del(key) {
    try {
      const deleted = await this.client.del(key);
      return deleted === 1; // True if deleted successfully
    } catch (err) {
      console.error(`Redis DEL Error for key "${key}":`, err);
      throw err;
    }
  }
}

// Create and export an instance
