package main

import (
	"fmt"
	"strings"
)

func detectDoubleNegative(sentence string) {
	// 1. Define a slice of common negative words to watch for in double negatives
	negativeWords := []string{"not", "never", "rarely", "seldom", "no", "nor", "without"}

	// 2. Tokenize the sentence into words for analysis
	words := strings.Split(sentence, " ")

	// 3. Iterate through each word and its preceding context
	for i := range words {
		currentWord := words[i]
		//  Check if the current word IS a negative word from our list AND
		//  if the previous word is "not" (forming "not + negative word")
		if contains(negativeWords, currentWord) && i > 0 && words[i-1] == "not" {
			fmt.Printf("Double negative detected in sentence: '%s'  (pattern: %s %s)\n", sentence, words[i-1], currentWord)
			return // Exit after finding one instance
		}
	}
	fmt.Println("No double negative found in the sentence.")
}

// Helper function to efficiently check for word presence in a slice
func contains(slice []string, item string) bool {
	for _, v := range slice {
		if v == item {
			return true
		}
	}
	return false
}

func main() {
	sentences := []string{
		"He isn't not worried about the coronavirus situation",
		"She rarely visits, she seldom goes out these days",
		"I have no complaints.",
		"They did enjoy the movie, nor disliked it.",
		"He is going without any hesitation.",
		"This document contains important information.", // No double negative
	}

	for _, sentence := range sentences {
		detectDoubleNegative(sentence)
	}
}
