				foundDoubleNeg = true
				break // Exit inner loop once a match is found
			}
		}
		if foundDoubleNeg {
			break // Exit outer loop after detecting a double negative
		}
	}

	// If no double negative pattern is found within the loop,  implicit statement
	if !foundDoubleNeg {
		fmt.Println("No double negative found in the sentence.")
	}
}

func main() {
