# Define function to check SID usage within domain SIDHistory
function Check-RestrictedSIDInACL {
    param(
        [string]$FolderPath,
        [string]$DomainController = (Get-ADDomainController).Name # Default to current domain controller
    )

    # Get all files and folders recursively within the specified path
    Get-ChildItem -Path $FolderPath -Recurse | ForEach-Object {
        # Extract ACL information
        $acl = Get-Acl $_.FullName

        # Iterate through each Access Control Entry (ACE) in the ACL
        $acl.Access | ForEach-Object {
            # Check if the ACE grants access using a Security Identifier (SID)
            if ($_.IdentityReference -isnot $null -and $_.IdentityReference.GetType() -eq "System.Security.Principal.SecurityIdentifier") {
                $sid = $_.IdentityReference.Value

                # Query Domain for SID History and filter for exclusive occurrences
                $userOrGroupSids = Get-ADUser -Filter * -Properties samaccountname,sidhistory |
                    Select-Object samaccountname,@{Name="ExclusiveSIDs";Expression={$_.sidhistory -split ';' | Where-Object { $_ -match $sid -and $_ -ne $sid }} }
                $groupSids = Get-ADGroup -Filter * -Properties samaccountname,sidhistory |
                    Select-Object samaccountname,@{Name="ExclusiveSIDs";Expression={$_.sidhistory -split ';' | Where-Object { $_ -match $sid -and $_ -ne $sid }}}

                # Combine results and check for exclusivity
                $exclusiveSids = ($userOrGroupSids | FlattenProperty ExclusiveSIDs) + ($groupSids | FlattenProperty ExclusiveSids)
                if ($exclusiveSids.Count -eq 0) {
                    Write-Warning "WARNING: Folder '$_' ACL contains SID '$sid' NOT found exclusively in any user/group SIDHistory on domain controller '$DomainController'"
                    # Add logging or further action as needed (e.g., reporting, alerting)
                }
            }
        }
    }
}

