# Define function to recursively check folder ACLs and SIDHistory
function Check-RecursiveACLs {
    param(
        [Parameter(Mandatory=$true)]
        [string]$FolderPath,
        [string]$DomainController = (Get-ADDomainController).Name # Default to current domain controller
    )

    # Get-ADPrincipalGroupMembership cmdlet requires domain context, hence using DomainController
    $UserAndGroupSIDs = @(Get-ADGroupMember -Identity "*ALL*" -Properties ObjectClass,SamAccountName -Server $DomainController | Select-Object -ExpandProperty ObjectSid)
    $UserAndGroupSIDs += (Get-ADUser -Filter * -Properties ObjectClass,SamAccountName -Server $DomainController | Select-Object -ExpandProperty ObjectSid)

    # Build a hashtable mapping SIDs to User/Group names for clarity in output
    $SIDToNameMapping = @{}
    foreach ($sid in $UserAndGroupSIDs) {
        $name = (Get-ADObject -Identity $sid -Properties SamAccountName, Name -Server $DomainController).SamAccountName
        $SIDToNameMapping[$sid] = $name
    }

    # Recursive directory traversal with ACL analysis
    $FoldersToProcess = Get-ChildItem -Path $FolderPath -Recurse -Directory
    foreach ($folder in $FoldersToProcess) {
        Write-Host "Analyzing ACLs for: $($folder.FullName)" -ForegroundColor Cyan

        # Get ACL entries and filter for SIDs
        $ACL = Get-Acl -Path $folder.FullName
        $SIDEntries = $ACL.Access | Where-Object {$_.FileSystemRights -ne 'None' -and $_.IdentityReference -isnot $null -and $_.IdentityReference -match 'S-' }

        # Compare each SID against User/Group SIDHistory
        foreach ($entry in $SIDEntries) {
            $sidToCheck = $entry.IdentityReference
            if (!( $sidToCheck in $SIDToNameMapping )) {
                Write-Warning "WARNING: Found SID $($sidToCheck) in ACL of $($folder.FullName) NOT present in domain User/Group SIDHistory."
                Write-Verbose "  - Corresponding User/Group (if any, couldn't be mapped) : $($entry.IdentityReference -replace 'S-', '' )" #verbose output for debugging
            }
